import json
from pathlib import Path


def classify(report, returncode, selected=False):
    if returncode is None or not isinstance(report, dict):
        return "INFRASTRUCTURE_FAILED"
    if report.get("status") == "infrastructure_failed":
        return "INFRASTRUCTURE_FAILED"
    if returncode != 0 or report.get("status") != "passed":
        return "FAILED"
    coverage = report.get("coverage", {})
    expected = "selected" if selected else "complete"
    scenarios = report.get("scenarios", [])
    summary = coverage.get("scenarios", {})
    if coverage.get("scope") != expected or coverage.get("status") != expected:
        return "FAILED"
    if not scenarios or any(item.get("status") != "passed" for item in scenarios):
        return "FAILED"
    if summary.get("unrun") != 0 or summary.get("failed") != 0:
        return "FAILED"
    if summary.get("completed") != len(scenarios) or summary.get("total") != len(scenarios):
        return "FAILED"
    if any(coverage.get("manifest_errors", {}).values()):
        return "FAILED"
    if not selected and coverage.get("executable_uncovered"):
        return "FAILED"
    return "SELECTED_PASS" if selected else "PASS"


def write_summary(directory, report, returncode, selected, provenance, error=None):
    directory = Path(directory)
    directory.mkdir(parents=True, exist_ok=True)
    status = classify(report, returncode, selected)
    if error:
        status = "INFRASTRUCTURE_FAILED"
    result = {
        "schema_version": 1,
        "status": status,
        "runner_returncode": returncode,
        "error": error,
        "provenance": provenance,
        "upstream_result": report,
    }
    (directory / "result.json").write_text(json.dumps(result, indent=2) + "\n", encoding="utf-8")
    lines = ["# Endstone event lab", "", f"Status: **{status}**", "",
             "PASS applies only to PR #526's executable scope; unsupported events remain excluded.",
             "A cancellation flag assertion does not necessarily prove the game-side effect was blocked.", "",
             f"Runner exit code: `{returncode}`", "",
             f"Upstream SHA: `{provenance.get('upstream_sha', 'unverified')}`", ""]
    if error:
        lines.extend([f"Infrastructure error: {error}", ""])
    if report:
        lines.extend(["| Scenario | Result |", "|---|---|"])
        for item in report.get("scenarios", []):
            name = str(item.get("name", "")).replace("|", "\\|").replace("\n", " ")
            lines.append(f"| {name} | {item.get('status')} |")
        unsupported = report.get("coverage", {}).get("categories", {}).get("no_fire_site_or_unsupported", {})
        lines.extend(["", "Excluded events:", ""])
        for name, reason in unsupported.get("reasons", {}).items():
            lines.append(f"- {name}: {reason}")
    (directory / "summary.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
    return status

import copy
from pathlib import Path
import sys
import unittest

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / 'scripts'))
from results import classify


class ResultContract(unittest.TestCase):
    def setUp(self):
        self.report = {
            'status': 'passed',
            'scenarios': [{'name': 'example', 'status': 'passed'}],
            'coverage': {'scope': 'complete', 'status': 'complete',
                         'scenarios': {'total': 1, 'completed': 1, 'failed': 0, 'unrun': 0},
                         'manifest_errors': {}, 'executable_uncovered': []},
        }

    def test_complete_pass(self):
        self.assertEqual(classify(self.report, 0), 'PASS')

    def test_missing_report_cannot_pass(self):
        self.assertEqual(classify(None, 0), 'INFRASTRUCTURE_FAILED')

    def test_crash_after_pass_cannot_pass(self):
        self.assertEqual(classify(self.report, 1), 'FAILED')

    def test_selected_is_not_full_pass(self):
        self.report['coverage'].update(scope='selected', status='selected')
        self.assertEqual(classify(self.report, 0), 'FAILED')
        self.assertEqual(classify(self.report, 0, True), 'SELECTED_PASS')

    def test_unrun_failed_empty_or_uncovered_cannot_pass(self):
        for variant in ['unrun', 'failed', 'empty', 'uncovered']:
            with self.subTest(variant=variant):
                report = copy.deepcopy(self.report)
                if variant in ['unrun', 'failed']:
                    report['coverage']['scenarios'][variant] = 1
                elif variant == 'empty':
                    report['scenarios'] = []
                else:
                    report['coverage']['executable_uncovered'] = ['PlayerJoinEvent']
                self.assertEqual(classify(report, 0), 'FAILED')

    def test_manifest_error_cannot_pass(self):
        self.report['coverage']['manifest_errors'] = {'duplicate_events': ['PlayerJoinEvent']}
        self.assertEqual(classify(self.report, 0), 'FAILED')


if __name__ == '__main__':
    unittest.main()
